// Package transport provides predefined transport protocol.
package transport

import "strings"

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	// Framed is now the default base protocol (value 0)
	Framed Protocol = 0

	// Base protocol flags
	TTHeader Protocol = 1 << iota
	PurePayload
	HTTP
	GRPC
	HESSIAN2

	// Streaming mode flags (dedicated bits)
	TTHeaderStreaming Protocol = 64  // Dedicated flag for TTHeader streaming
	GRPCStreaming     Protocol = 128 // Dedicated flag for gRPC streaming

	// Legacy STREAMING flag (deprecated, kept for compatibility)
	STREAMING Protocol = 32

	// Composite protocols
	TTHeaderFramed = TTHeader | Framed
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
// Handles both simple and composite protocol values.
func (tp Protocol) String() string {
	// Handle exact matches first (most common cases)
	switch tp {
	case Framed:
		return "Framed"
	case TTHeader:
		return "TTHeader"
	case PurePayload:
		return "PurePayload"
	case HTTP:
		return "HTTP"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	case TTHeaderFramed:
		return "TTHeaderFramed"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	case STREAMING:
		return "STREAMING"
	}

	// Handle composite protocols (bitwise combinations)
	if tp == 0 {
		return "Framed" // Default
	}

	var parts []string

	// Check each flag
	if tp&TTHeader != 0 {
		parts = append(parts, "TTHeader")
	}
	if tp&PurePayload != 0 {
		parts = append(parts, "PurePayload")
	}
	if tp&Framed != 0 && tp != Framed {
		parts = append(parts, "Framed")
	}
	if tp&HTTP != 0 {
		parts = append(parts, "HTTP")
	}
	if tp&GRPC != 0 {
		parts = append(parts, "GRPC")
	}
	if tp&HESSIAN2 != 0 {
		parts = append(parts, "Hessian2")
	}
	if tp&STREAMING != 0 {
		parts = append(parts, "STREAMING")
	}
	if tp == TTHeaderStreaming {
		return "TTHeaderStreaming"
	}
	if tp == GRPCStreaming {
		return "GRPCStreaming"
	}

	if len(parts) > 0 {
		return strings.Join(parts, "|")
	}

	return Unknown
}

// IsStreaming returns true if the protocol supports streaming.
func (tp Protocol) IsStreaming() bool {
	return tp == TTHeaderStreaming || tp == GRPCStreaming || tp&STREAMING != 0
}
