// Package transport provides predefined transport protocol.
package transport

import "strings"

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
// NOTE: Existing constant values must be preserved for backward compatibility.
const (
	PurePayload Protocol = 0  // Must remain 0
	TTHeader    Protocol = 2  // Must remain 2
	Framed      Protocol = 4  // Must remain 4
	HTTP        Protocol = 8  // Must remain 8
	GRPC        Protocol = 16 // Must remain 16
	HESSIAN2    Protocol = 32 // Must remain 32

	// Streaming mode flags (dedicated bits for new streaming protocols)
	TTHeaderStreaming Protocol = 64  // Dedicated flag for TTHeader streaming
	GRPCStreaming     Protocol = 128 // Dedicated flag for gRPC streaming

	// Composite protocols
	TTHeaderFramed = TTHeader | Framed // 2 | 4 = 6
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
// Handles both simple and composite protocol values.
func (tp Protocol) String() string {
	// Handle exact matches first (most common cases)
	switch tp {
	case PurePayload:
		return "PurePayload"
	case TTHeader:
		return "TTHeader"
	case Framed:
		return "Framed"
	case HTTP:
		return "HTTP"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	case TTHeaderFramed:
		return "TTHeaderFramed"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	}

	// Handle composite protocols (bitwise combinations)
	// Build parts in ascending bit order for consistent output
	var parts []string

	// Check flags in ascending order (by bit value)
	if tp&PurePayload != 0 && tp != PurePayload {
		parts = append(parts, "PurePayload")
	}
	if tp&TTHeader != 0 {
		parts = append(parts, "TTHeader")
	}
	if tp&Framed != 0 {
		parts = append(parts, "Framed")
	}
	if tp&HTTP != 0 {
		parts = append(parts, "HTTP")
	}
	if tp&GRPC != 0 {
		parts = append(parts, "GRPC")
	}
	if tp&HESSIAN2 != 0 {
		parts = append(parts, "Hessian2")
	}
	if tp&TTHeaderStreaming != 0 {
		parts = append(parts, "TTHeaderStreaming")
	}
	if tp&GRPCStreaming != 0 {
		parts = append(parts, "GRPCStreaming")
	}

	if len(parts) > 0 {
		return strings.Join(parts, "|")
	}

	return Unknown
}

// IsStreaming returns true if the protocol supports streaming.
func (tp Protocol) IsStreaming() bool {
	return tp == TTHeaderStreaming || tp == GRPCStreaming
}
